CREATE DATABASE IF NOT EXISTS gatsibo_rice CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gatsibo_rice;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','hr','store','production','sales','accountant') NOT NULL DEFAULT 'sales',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employees(id INT AUTO_INCREMENT PRIMARY KEY,employee_no VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,phone VARCHAR(50),department VARCHAR(100),job_title VARCHAR(100),hire_date DATE,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','late','leave') NOT NULL,check_in TIME,notes TEXT,recorded_by INT,UNIQUE KEY uq_att(employee_id,attendance_date),FOREIGN KEY(employee_id) REFERENCES employees(id),FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,category VARCHAR(100),unit VARCHAR(30) DEFAULT 'kg',quantity DECIMAL(14,2) NOT NULL DEFAULT 0,reorder_level DECIMAL(14,2) NOT NULL DEFAULT 0,cost_price DECIMAL(14,2) NOT NULL DEFAULT 0,selling_price DECIMAL(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_movements(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,movement_type ENUM('in','out','adjustment') NOT NULL,quantity DECIMAL(14,2) NOT NULL,reference VARCHAR(100),notes TEXT,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(50),email VARCHAR(190),address TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NULL,product_id INT NOT NULL,quantity DECIMAL(14,2) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,total DECIMAL(14,2) NOT NULL,payment_status ENUM('paid','unpaid','partial') DEFAULT 'paid',created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY,category VARCHAR(100),description TEXT,amount DECIMAL(14,2) NOT NULL,expense_date DATE NOT NULL,payment_method VARCHAR(50),recorded_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS production_records(id INT AUTO_INCREMENT PRIMARY KEY,production_date DATE NOT NULL,input_kg DECIMAL(14,2) NOT NULL,output_kg DECIMAL(14,2) NOT NULL,waste_kg DECIMAL(14,2) NOT NULL DEFAULT 0,product_id INT NULL,notes TEXT,recorded_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL,FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,action VARCHAR(120) NOT NULL,details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
